# frozen_string_literal: true

require "test_helper"

# every loading state shows a loading yak — A · Trot (0.8 s) or B · Haul (1.6 s), picked at random per
# mount — instead of the ring spinner. Generated by scripts/logo/loader.py; never edit the SVGs or yakLoaders.ts.
class YakLoaderTest < Minitest::Test
  ROOT = File.expand_path("../..", __dir__)
  CYCLE = { "a" => "0.8", "b" => "1.6" }.freeze
  SKINS = { "light" => %w[#16181d #a8380a], "dark" => %w[#eceef2 #ff8a3d] }.freeze # = app.css --ink / --accent

  def read(path) = File.read(File.join(ROOT, path))

  def test_static_loaders_per_variant_and_skin
    CYCLE.each do |v, secs|
      SKINS.each do |skin, (ink, accent)|
        f = "public/static/yak-loader-#{v}-#{skin}.svg"
        s = read(f)
        assert_equal [secs], s.scan(/animation:[\w-]+ ([\d.]+)s/).flatten.uniq, "#{f}: one #{secs} s cycle"
        assert_includes s, "@media (prefers-reduced-motion:reduce){.y#{v} *{animation:none!important}}", f
        assert_includes s, %(fill="#{ink}"), f
        assert_includes s, %(fill="#{accent}"), f
        refute_match(/currentColor|var\(--|<script|\sid="/, s, f)
        still = read("public/static/yak-loader-#{v}-#{skin}-still.svg")
        refute_match(/<style|@keyframes|animation/, still, "#{f}: the reduced-motion copy stands still")
        assert_includes still, %(fill="#{accent}"), "#{f}: still copy keeps the cards"
      end
    end
  end

  def test_haul_starts_on_the_full_stack
    s = read("public/static/yak-loader-b-light.svg")
    assert_equal 6, s.scan("animation-delay:-.96s").size, "cards, body, head, tail start at 60 % (stacked)"
  end

  def test_spa_loader_follows_the_skin_tokens
    ts = read("frontend/src/components/yakLoaders.ts")
    CYCLE.each_key { |v| assert_match(/^  #{v}: '<svg class="y#{v}"/, ts) } # the literal as Prettier prints it
    assert_includes ts, "currentColor"
    assert_includes ts, "var(--accent)"
    refute_match(/\sid=\\?"/, ts, "no ids: several loaders share a page")
  end

  def test_every_loading_state_uses_the_yak
    assert_includes read("frontend/src/components/States.tsx"), "<YakLoader /> loading"
    css = read("frontend/src/styles/spa.css")
    refute_match(/^\.spin\s*\{/, css, "the ring spinner is gone")
    CYCLE.each_key do |v|
      SKINS.each_key { |skin| assert_includes css, "/static/yak-loader-#{v}-#{skin}.svg" }
    end
    assert_includes read("frontend/src/components/Board.tsx"), %(className="yak-board" data-yak={yak})
    assert_match(/animation: yak-in 0s 0?\.25s both/, css, "a fast load never flashes the loader")
    assert_match(/@media \(prefers-reduced-motion: reduce\) \{[^@]*yak-loader-a-light-still\.svg/m, css)
    assert_includes read("frontend/src/routes/Projects.tsx"), %(<Loading what="boards" inline />)
  end
end
